values
  ('NL', 'NL-P-06', 'Inkoop 6 % — aftrekbaar, tot 2018', '{"en":"Purchase 6% — deductible, until 2018"}'::jsonb, null, 'percent', 6, 'purchase', 'domestic', date '2012-10-01', date '2018-12-31', 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I, in de tekst geldend tot en met 31 december 2018 — 6 percent; vervangen door 9 percent bij het Belastingplan 2019 (Stb. 2018, 504). De geschiedenis van dit pakket begint op 1 oktober 2012, de dag van het tarief van 21 percent: de oudere tarieven staan er niet in; Wet op de omzetbelasting 1968, art. 15, lid 1, onderdeel a — aftrek van de belasting die andere ondernemers op een voorgeschreven factuur in rekening hebben gebracht', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob-2018', null, null, null),
  ('NL', 'NL-P-09', 'Inkoop 9 % — aftrekbaar', '{"en":"Purchase 9% — deductible"}'::jsonb, null, 'percent', 9, 'purchase', 'domestic', date '2019-01-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I — 9 percent voor de goederen en diensten van tabel I, sinds 1 januari 2019 (Belastingplan 2019, Stb. 2018, 504, dat «6 percent» door «9 percent» verving); Wet op de omzetbelasting 1968, art. 15, lid 1, onderdeel a — aftrek van de belasting die andere ondernemers op een voorgeschreven factuur in rekening hebben gebracht — rubriek 5b', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'stb-2018-504', null, null, null),
  ('NL', 'NL-P-21', 'Inkoop 21 % — aftrekbaar', '{"en":"Purchase 21% — deductible"}'::jsonb, null, 'percent', 21, 'purchase', 'domestic', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 15, lid 1, onderdeel a — aftrek van de belasting die andere ondernemers op een voorgeschreven factuur in rekening hebben gebracht — rubriek 5b', 'S', null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-21-BUA', 'Inkoop 21 % — aftrek uitgesloten (BUA)', '{"en":"Purchase 21% — deduction excluded (BUA)"}'::jsonb, 'Niet-aftrekbare btw: het volle bedrag komt op de kostenrekening, niets op rubriek 5b.', 'percent', 21, 'purchase', 'domestic', date '2012-10-01', null, 'Besluit uitsluiting aftrek omzetbelasting 1968, art. 1, lid 1 — geen aftrek voor goederen en diensten die worden gebezigd voor het voeren van een zekere staat, voor relatiegeschenken en giften, of voor persoonlijke doeleinden van het personeel; art. 1a stelt een drempel per persoon per jaar, die in de administratie en niet in de btw-code wordt beoordeeld. De btw volgt de kostenrekening van de regel', 'S', null, 130, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'bua', null, null, null),
  ('NL', 'NL-P-BEU-21', 'Dienst van een ondernemer van buiten de EU, 21 %', '{"en":"Service from a business outside the EU, 21%"}'::jsonb, null, 'percent', 21, 'purchase', 'foreign_services_received', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 6, lid 1, en art. 12, lid 2 — de dienst van een ondernemer van buiten de EU die de btw naar u verlegt; rubriek 4a, aftrek in 5b (art. 15, lid 1, onderdeel c)', null, null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-ICD-21', 'Dienst van een ondernemer uit een andere lidstaat, 21 %', '{"en":"Service from a business in another Member State, 21%"}'::jsonb, null, 'percent', 21, 'purchase', 'intracom_acquisition_services', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 6, lid 1, en art. 12, lid 2 — de dienst van een ondernemer uit een andere lidstaat is in Nederland belast en de belasting wordt van de afnemer geheven; rubriek 4b, aftrek in 5b (art. 15, lid 1, onderdeel c)', 'K', 'VATEX-EU-IC', 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-ICV-09', 'Intracommunautaire verwerving van goederen, 9 %', '{"en":"Intra-Community acquisition of goods, 9%"}'::jsonb, null, 'percent', 9, 'purchase', 'intracom_acquisition_goods', date '2019-01-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I — 9 percent voor de goederen en diensten van tabel I, sinds 1 januari 2019 (Belastingplan 2019, Stb. 2018, 504, dat «6 percent» door «9 percent» verving); Wet op de omzetbelasting 1968, art. 1, onderdeel b, en art. 17a — intracommunautaire verwerving van goederen; art. 17c — maatstaf; art. 15, lid 1, onderdeel b — aftrek; rubriek 4b en 5b', 'K', 'VATEX-EU-IC', 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-ICV-21', 'Intracommunautaire verwerving van goederen, 21 %', '{"en":"Intra-Community acquisition of goods, 21%"}'::jsonb, null, 'percent', 21, 'purchase', 'intracom_acquisition_goods', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 1, onderdeel b, en art. 17a — intracommunautaire verwerving van goederen; art. 17c — maatstaf; art. 15, lid 1, onderdeel b — aftrek; rubriek 4b en 5b', 'K', 'VATEX-EU-IC', 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-INV-21', 'Invoer met vergunning artikel 23, 21 %', '{"en":"Import under an article 23 licence, 21%"}'::jsonb, null, 'percent', 21, 'purchase', 'import', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 23 — verlegging van de invoerbtw naar een aangewezen ondernemer (vergunning artikel 23); de btw komt in rubriek 4a in plaats van bij de Douane, en wordt in 5b afgetrokken (art. 15, lid 1, onderdeel e)', null, null, 210, 'vat', true, array['buyer_certificate']::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-P-VERL-09', 'Inkoop — btw naar u verlegd, 9 %', '{"en":"Purchase — VAT reverse-charged to you, 9%"}'::jsonb, null, 'percent', 9, 'purchase', 'domestic_reverse_charge', date '2019-01-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I — 9 percent voor de goederen en diensten van tabel I, sinds 1 januari 2019 (Belastingplan 2019, Stb. 2018, 504, dat «6 percent» door «9 percent» verving); Wet op de omzetbelasting 1968, art. 12, lid 5, en Uitvoeringsbesluit omzetbelasting 1968, art. 24b en volgende — de belasting wordt geheven van de afnemer; rubriek 2a, en aftrek in rubriek 5b op grond van art. 15, lid 1, onderdeel c', 'AE', 'VATEX-EU-AE', 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'uitvoeringsbesluit-ob', null, null, null),
  ('NL', 'NL-P-VERL-21', 'Inkoop — btw naar u verlegd, 21 %', '{"en":"Purchase — VAT reverse-charged to you, 21%"}'::jsonb, null, 'percent', 21, 'purchase', 'domestic_reverse_charge', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321); Wet op de omzetbelasting 1968, art. 12, lid 5, en Uitvoeringsbesluit omzetbelasting 1968, art. 24b en volgende — de belasting wordt geheven van de afnemer; rubriek 2a, en aftrek in rubriek 5b op grond van art. 15, lid 1, onderdeel c', 'AE', 'VATEX-EU-AE', 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'uitvoeringsbesluit-ob', null, null, null),
  ('NL', 'NL-P-VRIJ', 'Inkoop zonder btw — vrijgesteld of niet belast', '{"en":"Purchase without VAT — exempt or not taxed"}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 11 — vrijgestelde prestaties; een inkoop zonder btw komt niet op de aangifte', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-S-00', 'Verkoop 0 % — tabel II, binnenland', '{"en":"Sale 0% — table II, domestic"}'::jsonb, null, 'percent', 0, 'sale', 'domestic', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel b, en tabel II — het nultarief voor de goederen en diensten van tabel II, onder de voorwaarden van het Uitvoeringsbesluit omzetbelasting 1968; op de aangifte in rubriek 1e, behalve uitvoer (3a) en intracommunautaire leveringen (3b), die hun eigen code hebben', 'Z', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-S-06', 'Verkoop 6 % — verlaagd tarief tot 2018', '{"en":"Sale 6% — reduced rate until 2018"}'::jsonb, null, 'percent', 6, 'sale', 'domestic', date '2012-10-01', date '2018-12-31', 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I, in de tekst geldend tot en met 31 december 2018 — 6 percent; vervangen door 9 percent bij het Belastingplan 2019 (Stb. 2018, 504). De geschiedenis van dit pakket begint op 1 oktober 2012, de dag van het tarief van 21 percent: de oudere tarieven staan er niet in', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob-2018', null, null, null),
  ('NL', 'NL-S-09', 'Verkoop 9 % — verlaagd tarief', '{"en":"Sale 9% — reduced rate"}'::jsonb, null, 'percent', 9, 'sale', 'domestic', date '2019-01-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel a, en tabel I — 9 percent voor de goederen en diensten van tabel I, sinds 1 januari 2019 (Belastingplan 2019, Stb. 2018, 504, dat «6 percent» door «9 percent» verving)', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'stb-2018-504', null, null, null),
  ('NL', 'NL-S-21', 'Verkoop 21 % — algemeen tarief', '{"en":"Sale 21% — standard rate"}'::jsonb, null, 'percent', 21, 'sale', 'domestic', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 1 — «De belasting bedraagt 21 percent», sinds 1 oktober 2012 (Stb. 2012, 321)', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
  ('NL', 'NL-S-ICD', 'Dienst aan een ondernemer in een andere lidstaat — btw verlegd', '{"en":"Service to a business in another Member State — VAT reverse-charged"}'::jsonb, null, 'percent', 0, 'sale', 'intracom_services', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 6, lid 1 — de dienst is belastbaar waar de afnemende ondernemer is gevestigd; art. 37a, lid 1, onderdeel c — de afnemer komt op de opgaaf ICP; rubriek 3b van de aangifte. De heffing bij de afnemer volgt uit art. 196 van richtlijn 2006/112/EG', 'K', 'VATEX-EU-IC', 70, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
