  ('NL', 'NL-S-UIT', 'Uitvoer van goederen buiten de EU — 0 %', '{"en":"Export of goods outside the EU — 0%"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2012-10-01', null, 'Wet op de omzetbelasting 1968, art. 9, lid 2, onderdeel b, en tabel II, onderdeel a, post 2 — goederen die door een ondernemer worden uitgevoerd uit de Unie; rubriek 3a van de aangifte', 'G', 'VATEX-EU-G', 80, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'wet-ob', null, null, null),
