insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('NL', 'NL-OB-AANGIFTE', 'Aangifte omzetbelasting (btw-aangifte)', array['month', 'quarter', 'year']::declaration_period[], 'quarter'::declaration_period, date '2026-01-01', null, 'Wet op de omzetbelasting 1968, art. 14, lid 1 — de in een tijdvak verschuldigd geworden belasting wordt op aangifte voldaan. Tijdvak: Uitvoeringsregeling Algemene wet inzake rijksbelastingen 1994, art. 25, lid 1 — het kalenderkwartaal, of de kalendermaand als de inspecteur dat vordert of de belastingplichtige over een kalendermaand aangifte doet; lid 3 — in bijzondere gevallen een ander tijdvak, zoals het jaar. Het kwartaal geldt dus voor iedereen die niets anders heeft gevraagd of opgelegd gekregen, en is daarom voorgesteld. De rubrieken zijn die van de aangifte 2026, zoals de Belastingdienst ze toelicht en in de Nederlandse Taxonomie publiceert', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Algemene wet inzake rijksbelastingen, art. 19, lid 1 — de belasting wordt binnen één maand na het einde van het tijdvak betaald; art. 10, lid 2 — de aangifte wordt gedaan binnen een door de inspecteur gestelde termijn van ten minste een maand na het einde van het tijdvak. De uiterste datums staan in de aangiftebrief en in Mijn Belastingdienst Zakelijk; art. 19, lid 5, sluit de Algemene termijnenwet uit, zodat een datum die op een zaterdag, zondag of feestdag valt niet verschuift', 'awr', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

