insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('NL-BMJ-C', 'NL', 'default', 'Balans — model C (kleine rechtspersoon, verticaal)', 'balance_sheet', 'NL-GAAP', date '2016-01-01', null, 'Besluit modellen jaarrekening, art. 1, lid 2 — een vennootschap waarop art. 2:396 BW van toepassing is (klein) mag voor de balans model C kiezen; Burgerlijk Wetboek Boek 2, art. 364 tot en met 376 en art. 396, lid 3 — de indeling van de balans en de beperking voor een kleine rechtspersoon. De regels volgen de koppeling die de dataset «RGS NL en EN labels» van elke RGS-code naar de begrippen jenv-bw2 van de Nederlandse Taxonomie legt. Regel I staat niet in het model: het is de controletelling die tegenover E hoort te staan', 'bmj'),
  ('NL-BMJ-E', 'NL', 'default', 'Winst- en verliesrekening — model E (categoriale indeling, verticaal)', 'income_statement', 'NL-GAAP', date '2016-01-01', null, 'Besluit modellen jaarrekening, art. 1, lid 1 — de winst- en verliesrekening van een naamloze of besloten vennootschap wordt ingericht volgens model E of model F; Burgerlijk Wetboek Boek 2, art. 377, lid 3 — de categoriale indeling. Pensioenlasten en overige personeelsbeloningen staan onder sociale lasten, zoals het model ze samenneemt; art. 2:382 vraagt ze afzonderlijk in de toelichting. Model I, dat een kleine rechtspersoon mag kiezen en dat met de bruto-marge begint, is hetzelfde schema met de eerste regels samengenomen', 'bmj')
