update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Burgerlijk Wetboek Boek 6, art. 119a — wettelijke handelsrente vanaf de dertigste dag na ontvangst van de factuur, gelijk aan de herfinancieringsrente van de Europese Centrale Bank vermeerderd met acht procentpunten (art. 6:120, lid 2); art. 6:96, lid 4 — een vergoeding voor buitengerechtelijke incassokosten van ten minste 40 euro, zonder aanmaning verschuldigd',
  numbering_legal_reference     = 'Wet op de omzetbelasting 1968, art. 35a, lid 1, onderdeel b — de factuur vermeldt «een opeenvolgend nummer, met één of meer reeksen, waardoor de factuur eenduidig wordt geïdentificeerd». De wet eist een opeenvolgende en eenduidige nummering, geen vorm; gapless_per_year is de gebruikelijke lezing, sequential zou ook te verdedigen zijn',
  numbering_source_key          = 'wet-ob',
